import { useChat, type UseChatOptions } from "@ai-sdk/react"
import {
  lastAssistantMessageIsCompleteWithApprovalResponses,
  lastAssistantMessageIsCompleteWithToolCalls,
  type UIMessage,
} from "ai"

import {
  agentPhase,
  answeredClientTool,
  isWaitingOnUser,
  type ChatState,
} from "@/components/chat/chat-state"
import type { ToolRegistry } from "@/components/chat/tool-registry"

// useChat plus what every agent UI needs to know about it: is it busy, is it
// waiting on the person, what is the agent doing, which turn is live.
// Continues the turn automatically after a client tool answer or an
// approval, and never after a server tool that finished in-stream.
export function useAgentChat<M extends UIMessage>({
  tools = {},
  ...options
}: UseChatOptions<M> & { tools?: ToolRegistry }) {
  const chat = useChat<M>({
    sendAutomaticallyWhen: (o) =>
      (answeredClientTool(o.messages.at(-1), tools) &&
        lastAssistantMessageIsCompleteWithToolCalls(o)) ||
      lastAssistantMessageIsCompleteWithApprovalResponses(o),
    ...options,
  } as UseChatOptions<M>)

  const busy = chat.status === "submitted" || chat.status === "streaming"
  const last = chat.messages.at(-1)
  const waiting = !busy && isWaitingOnUser(last, tools)
  const phase = agentPhase(chat.status, waiting, last, tools)
  /** The live turn: the last assistant message while it streams or waits. */
  const activeIndex =
    (busy || waiting) && last?.role === "assistant" ? chat.messages.length - 1 : -1
  const state: ChatState =
    chat.status === "error" ? "error" : busy ? "streaming" : waiting ? "waiting" : "ready"

  return { ...chat, tools, busy, waiting, phase, activeIndex, state }
}

export type AgentChat<M extends UIMessage> = ReturnType<typeof useAgentChat<M>>

import type * as React from "react"
import type { UIMessage } from "ai"

import type { AgentPhase } from "@/components/ds/agent-orb"

// The tool registry is how an app teaches the chat to render its tools.
// The chat kit knows text, reasoning and sources; every `tool-*` part is
// looked up here by name. Unknown tools fall back to a generic trace line.
//
//   const tools = defineTools<MyMessage>()({
//     webSearch: { phase: "searching", render: (part) => <ToolLine … /> },
//     askQuestions: { client: true, render: (part, ctx) => <AskUser … /> },
//   })
//   <AssistantTurn message={m} tools={tools} … />

export type ToolContext = {
  /** Submit a client-executed tool's result (an answer, a sent draft). */
  addOutput: (output: unknown) => void
  /** Answer an approval request (`approval-requested` parts). */
  respond: (approved: boolean) => void
  /** True while this turn is still streaming. */
  streaming: boolean
}

export type ToolDefinition<P = unknown> = {
  render: (part: P, ctx: ToolContext) => React.ReactNode
  /**
   * Client-executed: the person supplies the output (questions, drafts).
   * While such a part is `input-available` the chat waits on the person,
   * and supplying the output continues the turn automatically.
   */
  client?: boolean
  /** What the agent orb shows while this tool runs. Default "working". */
  phase?: AgentPhase
}

export type ToolRegistry = Record<string, ToolDefinition<never>>

/** Names of the typed tools carried by a message type. */
export type ToolNames<M extends UIMessage> =
  M["parts"][number] extends infer P
    ? P extends { type: `tool-${infer N}` }
      ? N
      : never
    : never

/** The part type of one tool, with its input/output types and states. */
export type ToolPartOf<M extends UIMessage, N extends string> = Extract<
  M["parts"][number],
  { type: `tool-${N}` }
>

/**
 * Type-safe registry for a message type: each renderer receives exactly its
 * tool's part (input, output and state narrowed).
 */
export function defineTools<M extends UIMessage>() {
  return <T extends { [N in ToolNames<M>]?: ToolDefinition<ToolPartOf<M, N>> }>(
    tools: T
  ) => tools as unknown as ToolRegistry
}

import { getToolName, isToolUIPart, type UIMessage } from "ai"

import type { AgentPhase } from "@/components/ds/agent-orb"
import type { ToolRegistry } from "@/components/chat/tool-registry"

// Pure reads of a transcript. No React here, so they are easy to reuse in
// tests, servers or other UIs.

type Part = UIMessage["parts"][number]

function toolParts(message?: UIMessage) {
  if (!message || message.role !== "assistant") return []
  return message.parts.filter(isToolUIPart)
}

/** The turn is paused on the person: an open client tool or an approval. */
export function isWaitingOnUser(message: UIMessage | undefined, tools: ToolRegistry) {
  return toolParts(message).some(
    (p) =>
      p.state === "approval-requested" ||
      (p.state === "input-available" && tools[getToolName(p)]?.client === true)
  )
}

/**
 * The person just supplied a client tool's output. Used to continue the turn
 * automatically; server tools that finish in-stream must not re-trigger.
 */
export function answeredClientTool(message: UIMessage | undefined, tools: ToolRegistry) {
  return toolParts(message).some(
    (p) => p.state === "output-available" && tools[getToolName(p)]?.client === true
  )
}

/** What the agent is doing right now, read from the trailing part. */
export function agentPhase(
  status: string,
  waiting: boolean,
  last: UIMessage | undefined,
  tools: ToolRegistry
): AgentPhase {
  if (waiting) return "waiting"
  if (status === "submitted") return "connecting"
  if (status !== "streaming") return "idle"
  if (!last || last.role !== "assistant") return "connecting"

  const part = [...last.parts]
    .reverse()
    .find((p: Part) => p.type !== "step-start" && p.type !== "source-url")
  if (!part) return "connecting"
  if (part.type === "reasoning") return part.state === "streaming" ? "thinking" : "composing"
  if (isToolUIPart(part)) {
    return part.state === "output-available"
      ? "composing"
      : (tools[getToolName(part)]?.phase ?? "working")
  }
  return "composing"
}

export type ChatState = "streaming" | "waiting" | "ready" | "done" | "error"
